//! P0-2 equivalence guard: Rust NCC must match OpenCV `TM_CCOEFF_NORMED`.
//!
//! Fixture is generated by `tools/refgen_cv2.py` (dev-only, needs cv2):
//! synthetic deterministic frame + templates + reference {score,x,y}.
//!
//! Why this matters: "we rewrote perception" is only credible if it agrees
//! numerically with the old implementation. Tolerance: score 1e-4, position exact.

use std::path::PathBuf;
use std::time::Instant;

use oas_perceive::{match_template, GrayImage, Matcher};
use oas_types::Rect;

fn data_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests").join("data")
}

/// .gray = b"OASG" + u32le width + u32le height + w*h bytes
fn read_gray(path: &PathBuf) -> GrayImage {
    let raw = std::fs::read(path).unwrap_or_else(|e| panic!("read {:?}: {e}", path));
    assert_eq!(&raw[0..4], b"OASG", "bad magic in {path:?}");
    let w = u32::from_le_bytes(raw[4..8].try_into().unwrap());
    let h = u32::from_le_bytes(raw[8..12].try_into().unwrap());
    let pixels = raw[12..].to_vec();
    assert_eq!(pixels.len(), (w * h) as usize, "size mismatch in {path:?}");
    GrayImage::new(w, h, pixels)
}

#[test]
fn ncc_matches_opencv_tm_ccoeff_normed() {
    let dir = data_dir();
    let refs: serde_json::Value =
        serde_json::from_str(&std::fs::read_to_string(dir.join("ref.json")).expect(
            "ref.json missing -> run: python tools/refgen_cv2.py crates/oas-perceive/tests/data",
        ))
        .expect("ref.json parse");

    let frame = read_gray(&dir.join("frame.gray"));
    let cases = refs["cases"].as_array().expect("cases array");
    assert!(!cases.is_empty(), "no cases in ref.json");

    let mut checked = 0usize;
    for c in cases {
        let name = c["name"].as_str().unwrap();
        let tpl = read_gray(&dir.join(c["tpl"].as_str().unwrap()));
        let roi = Rect {
            x: c["roi"][0].as_i64().unwrap() as i32,
            y: c["roi"][1].as_i64().unwrap() as i32,
            w: c["roi"][2].as_i64().unwrap() as i32,
            h: c["roi"][3].as_i64().unwrap() as i32,
        };
        let want_score = c["score"].as_f64().unwrap();
        let want_x = c["x"].as_i64().unwrap() as i32;
        let want_y = c["y"].as_i64().unwrap() as i32;

        let got = match_template(&frame, &tpl, Some(roi))
            .unwrap_or_else(|| panic!("case {name}: no match returned"));
        assert!(
            (got.score as f64 - want_score).abs() < 1e-4,
            "case {name}: score mismatch: rust={} opencv={}",
            got.score,
            want_score
        );
        assert_eq!(
            (got.x, got.y),
            (want_x, want_y),
            "case {name}: best position mismatch (rust=({},{}) opencv=({},{})",
            got.x,
            got.y,
            want_x,
            want_y
        );
        checked += 1;
    }
    assert_eq!(checked, cases.len());
    println!("equivalence OK: {checked} cases match OpenCV within 1e-4");
}

#[test]
fn ncc_speed_50_templates() {
    // Synthetic 1280x720 frame + 50 templates 56x46, each searched in its own
    // 160x140 ROI (the real usage shape: ROI-limited search).
    let w = 1280usize;
    let h = 720usize;
    let mut frame = GrayImage::new(w as u32, h as u32, vec![0u8; w * h]);
    let mut seed = 12345u64;
    let mut next = || {
        seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
        (seed >> 33) as u8
    };
    for v in frame.data.iter_mut() {
        *v = next();
    }

    let tw = 56usize;
    let th = 46usize;
    let templates: Vec<GrayImage> = (0..50)
        .map(|_| {
            let mut t = vec![0u8; tw * th];
            for v in t.iter_mut() {
                *v = next();
            }
            GrayImage::new(tw as u32, th as u32, t)
        })
        .collect();

    let rois: Vec<Rect> = (0..50)
        .map(|i| Rect {
            x: 40 + (i as i32 * 23) % 1000,
            y: 30 + (i as i32 * 17) % 500,
            w: 160,
            h: 140,
        })
        .collect();

    let started = Instant::now();
    // One Matcher per frame: the integral images are built ONCE and reused by
    // every template (building them per template was the real P0-2 slowdown).
    let matcher = Matcher::from_ref(&frame);
    let mut hits = 0usize;
    for (tpl, roi) in templates.iter().zip(rois.iter()) {
        if matcher.match_template(tpl, Some(*roi)).is_some() {
            hits += 1;
        }
    }
    let elapsed = started.elapsed();
    println!(
        "50 templates x 160x140 ROI on 1280x720: {:?} ({:.1} ms total, {:.2} ms/template, hits={})",
        elapsed,
        elapsed.as_secs_f64() * 1000.0,
        elapsed.as_secs_f64() * 1000.0 / 50.0,
        hits
    );
    // Debug builds are ~20x slower than release, so the guard must scale with
    // the build profile; the real target (<=1ms/template) is tracked as P0-2b
    // and measured in release. Here we only catch pathological regressions.
    let ceiling_s = if cfg!(debug_assertions) { 60.0 } else { 5.0 };
    assert!(
        elapsed.as_secs_f64() < ceiling_s,
        "NCC throughput regression: {elapsed:?} for 50 templates (ceiling {ceiling_s}s, debug={})",
        cfg!(debug_assertions)
    );
}
